SELECT t.Id , t.Nickname , t.Firstname , t.Lastname 
FROM Traders t WHERE t.DeceaseDate IS NOT NULL
ORDER BY t.Firstname , t.Lastname ;

SELECT p.Name  FROM Products p 
WHERE p.Name LIKE 'D%' OR p.Name LIKE '%o%o%'
ORDER BY p.Name ;

SELECT DISTINCT p.Name 
FROM Products p JOIN TradeLines tl ON p.Id = tl.ProductId 
ORDER BY p.Name ;

SELECT ss.Code , ss.Name , p.Name 
FROM SolarSystems ss JOIN Planets p ON ss.Id = p.SystemId 
WHERE ss.Name  LIKE 'Grif' OR ss.Name LIKE 'Akaers';

SELECT t.Nickname , t.Firstname , t.Lastname, ROUND(AVG(DATEDIFF(s.EndDate,s.StartDate)),1) DuradaMitjana
FROM Traders t LEFT JOIN Stays s ON t.Id = s.TraderId 
GROUP BY t.Id , t.Nickname , t.Firstname , t.Lastname;

SELECT t.Nickname , t.Firstname , t.Lastname , t.DeceaseDate 
FROM Traders t 
WHERE  MONTH(t.DeceaseDate) = 12;

SELECT t.Nickname , DATEDIFF(t.DeceaseDate , CURDATE())
FROM Traders t 
WHERE t.DeceaseDate IS NOT NULL;

SELECT p.Name, ss.Name as n2, ss.Code
FROM traders.Planets p
INNER JOIN traders.SolarSystems ss ON p.SystemId = ss.Id;

